/** 线状街道不参与踩点（与世界书变量更新规则一致） */
const 线状街道 = ['山河路', '商业步行街', '老城大街'];

function 束缚显眼(穿着: Record<string, string>, 束缚: Record<string, string>): number {
  let 加成 = 0;
  if (束缚.眼部 && 束缚.眼部 !== '无') 加成 += 10;
  if (束缚.脚踝 && 束缚.脚踝 !== '无') 加成 += 10;
  if (束缚.口部 && 束缚.口部 !== '无') {
    const 有口罩 = 穿着.面部 && 穿着.面部 !== '无';
    if (束缚.口部.includes('马具')) 加成 += 10;
    else if (!有口罩) 加成 += 5;
  }
  if (束缚.身体 && 束缚.身体 !== '无') {
    const 有上衣 = 穿着.上衣 && 穿着.上衣 !== '无';
    if (!有上衣) 加成 += 8;
  }
  if (束缚.腿部 && 束缚.腿部 !== '无') {
    const 长裙 = 穿着.下装 && 穿着.下装.includes('长裙');
    if (!长裙) 加成 += 5;
  }
  const 其他部位 = ['上肢', '手腕', '胸部', '乳头', '腰部', '阴部', '阴蒂', '小穴', '后穴', '足部'];
  for (const 部位 of 其他部位) {
    if (束缚[部位] && 束缚[部位] !== '无') 加成 += 3;
  }
  return 加成;
}

export function 计算露出程度(穿着: Record<string, string>, 束缚: Record<string, string>): number {
  let 分数 = 0;
  for (const [部位, 权重] of Object.entries(穿着权重)) {
    if (!穿着[部位] || 穿着[部位] === '无') 分数 += 权重;
  }
  分数 += 束缚显眼(穿着, 束缚);
  return Math.min(100, 分数);
}

export function 计算时段(小时: number): string {
  if (小时 >= 6 && 小时 < 9) return '早晨';
  if (小时 >= 9 && 小时 < 18) return '白天';
  if (小时 >= 18 && 小时 < 22) return '晚上';
  return '深夜';
}

export function 计算风险值(
  露出程度: number,
  区域: string,
  地点: string,
  小时: number,
  已踩点: string[] = [],
): number {
  const 基础 = 地区风险[区域] ?? 40;
  let 修正 = 地点修正[地点] ?? 1;
  if (!线状街道.includes(地点) && 已踩点.includes(地点)) 修正 *= 0.85;
  const 段 = 计算时段(小时);
  let 时段修正 = 1.0;
  if (段 === '晚上') 时段修正 = 区域 === '老城区' ? 1.1 : 0.8;
  if (段 === '深夜') 时段修正 = 区域 === '老城区' ? 1.2 : 0.6;
  const 风险 = (露出程度 * 基础) / 100 * 修正 * 时段修正;
  return Math.min(100, Math.max(0, Math.round(风险)));
}

/** 行动系数按脚部束缚：无拘束 1.0，脚镣 0.4，双脚捆一起 0.15，两者皆有约 0.1 */
export function 计算行动系数(束缚: Record<string, string>): number {
  const 无 = (部位: string) => !束缚[部位] || 束缚[部位] === '无';
  if (无('脚踝') && 无('腿部')) return 1.0;
  if (!无('脚踝') && !无('腿部')) return 0.1;
  if (!无('脚踝')) return 0.4;
  return 0.15;
}

/** 地图坐标换算距离（km）：画布约 0.007 km/px */
export function 计算距离公里(dx: number, dy: number): number {
  return Math.sqrt(dx * dx + dy * dy) * 0.007;
}

/** 移动耗时（分钟）= 距离 ÷（4.5 km/h × 行动系数） */
export function 计算步行分钟(距离公里数: number, 行动系数 = 1): number {
  if (行动系数 <= 0) return NaN;
  return (距离公里数 / (4.5 * 行动系数)) * 60;
}

export function 是否露出(露出程度: number): boolean {
  return 露出程度 > 0;
}

export function 计算露出等级(露出经验: number): string {
  if (露出经验 < 30) return '初尝';
  if (露出经验 < 80) return '试探';
  if (露出经验 < 150) return '大胆';
  if (露出经验 < 250) return '放纵';
  return '无惧';
}
